#nullable enable

class C
{
    void M1(object obj)
    {
        _ = (true == obj is string x and string y)
            ? x.ToString()
            : y.ToString(); // 1
    }

    void M2(object obj)
    {
        _ = (false == obj is string x and string y)
            ? x.ToString() // 2
            : y.ToString();
    }

    void M3(object obj)
    {
        _ = (true != obj is string x and string y)
            ? x.ToString() // 3
            : y.ToString();
    }

    void M4(object obj)
    {
        _ = (false != obj is string x and string y)
            ? x.ToString()
            : y.ToString(); // 4
    }
}

